CREATE TABLE IF NOT EXISTS "customers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Id of this customer in the product database. The billing system is a separate concern and joins back through this.
	"external_ref" VARCHAR(120) UNIQUE,
	-- Legal or trading name printed on the invoice.
	"name" VARCHAR(200) NOT NULL,
	-- Billing contact. Distinct from any login address; invoices go where finance lives.
	"email" VARCHAR(320) NOT NULL,
	-- ISO 4217. Fixed per customer, because a customer whose currency changes mid-life makes every historical total ambiguous.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- VAT or equivalent registration, needed for reverse-charge invoicing.
	"tax_id" VARCHAR(60),
	-- Running account balance in minor units. Negative means the customer is in credit; positive means money is owed outside an open invoice.
	"balance_minor" BIGINT NOT NULL DEFAULT 0,
	-- Customer id at the payment gateway, where the stored card actually lives.
	"payment_provider_ref" VARCHAR(120),
	-- Account creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "customers" IS 'Who is billed. Every amount in this schema is an integer number of minor units in this currency; nothing anywhere is a float, because a tenth of a cent multiplied by ten million API calls is a real number of dollars.';
COMMENT ON COLUMN "customers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "customers"."external_ref" IS 'Id of this customer in the product database. The billing system is a separate concern and joins back through this.';
COMMENT ON COLUMN "customers"."name" IS 'Legal or trading name printed on the invoice.';
COMMENT ON COLUMN "customers"."email" IS 'Billing contact. Distinct from any login address; invoices go where finance lives.';
COMMENT ON COLUMN "customers"."currency_code" IS 'ISO 4217. Fixed per customer, because a customer whose currency changes mid-life makes every historical total ambiguous.';
COMMENT ON COLUMN "customers"."tax_id" IS 'VAT or equivalent registration, needed for reverse-charge invoicing.';
COMMENT ON COLUMN "customers"."balance_minor" IS 'Running account balance in minor units. Negative means the customer is in credit; positive means money is owed outside an open invoice.';
COMMENT ON COLUMN "customers"."payment_provider_ref" IS 'Customer id at the payment gateway, where the stored card actually lives.';
COMMENT ON COLUMN "customers"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "meters" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Identifier used when reporting usage, e.g. api_requests or gb_hours.
	"key" VARCHAR(60) NOT NULL UNIQUE,
	-- Display name shown on the invoice line.
	"name" VARCHAR(160) NOT NULL,
	-- What one unit is: request, GB-hour, seat. Printed on the invoice, so it is copy as much as configuration.
	"unit_label" VARCHAR(40) NOT NULL,
	-- sum | max | last | unique_count. A seat meter is max over the period; an API meter is sum. This choice changes the bill more than the price does.
	"aggregation" VARCHAR(20) NOT NULL DEFAULT 'sum',
	-- up | down | nearest, applied when collapsing fractional units at the end of a period.
	"rounding" VARCHAR(16) NOT NULL DEFAULT 'up',
	-- Creation time.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "meters" IS 'What is being counted, defined once and reused by every plan. The aggregation lives here rather than on the price component because it is a property of the measurement, not of the commercial deal.';
COMMENT ON COLUMN "meters"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "meters"."key" IS 'Identifier used when reporting usage, e.g. api_requests or gb_hours.';
COMMENT ON COLUMN "meters"."name" IS 'Display name shown on the invoice line.';
COMMENT ON COLUMN "meters"."unit_label" IS 'What one unit is: request, GB-hour, seat. Printed on the invoice, so it is copy as much as configuration.';
COMMENT ON COLUMN "meters"."aggregation" IS 'sum | max | last | unique_count. A seat meter is max over the period; an API meter is sum. This choice changes the bill more than the price does.';
COMMENT ON COLUMN "meters"."rounding" IS 'up | down | nearest, applied when collapsing fractional units at the end of a period.';
COMMENT ON COLUMN "meters"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "price_plans" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Stable identifier used in code and in signup links.
	"code" VARCHAR(60) NOT NULL UNIQUE,
	-- Customer-facing plan name.
	"name" VARCHAR(160) NOT NULL,
	-- Currency all component prices are expressed in. A plan is priced in one currency; other currencies are other plans.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- month | year. Drives period boundaries and how annual commitments amortise.
	"billing_interval" VARCHAR(12) NOT NULL DEFAULT 'month',
	-- Plans are versioned rather than edited. Repricing creates a new row so existing subscriptions keep the terms they signed.
	"version" INTEGER NOT NULL DEFAULT 1,
	-- False for legacy and negotiated plans that must never appear on the pricing page.
	"is_public" BOOLEAN NOT NULL DEFAULT true,
	-- When the version became sellable.
	"effective_from" TIMESTAMP,
	-- Archived plans cannot take new subscriptions but still price the ones they carry.
	"archived_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "price_plans" IS 'The commercial package. It holds almost no pricing itself — the prices are in its components — which is what lets one plan combine a platform fee, a per-seat charge and two metered charges without a column per case.';
COMMENT ON COLUMN "price_plans"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "price_plans"."code" IS 'Stable identifier used in code and in signup links.';
COMMENT ON COLUMN "price_plans"."name" IS 'Customer-facing plan name.';
COMMENT ON COLUMN "price_plans"."currency_code" IS 'Currency all component prices are expressed in. A plan is priced in one currency; other currencies are other plans.';
COMMENT ON COLUMN "price_plans"."billing_interval" IS 'month | year. Drives period boundaries and how annual commitments amortise.';
COMMENT ON COLUMN "price_plans"."version" IS 'Plans are versioned rather than edited. Repricing creates a new row so existing subscriptions keep the terms they signed.';
COMMENT ON COLUMN "price_plans"."is_public" IS 'False for legacy and negotiated plans that must never appear on the pricing page.';
COMMENT ON COLUMN "price_plans"."effective_from" IS 'When the version became sellable.';
COMMENT ON COLUMN "price_plans"."archived_at" IS 'Archived plans cannot take new subscriptions but still price the ones they carry.';

CREATE TABLE IF NOT EXISTS "plan_components" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Plan this charge belongs to.
	"plan_id" BIGINT NOT NULL,
	-- Meter being charged for. Null for a flat platform fee that has no usage behind it.
	"meter_id" BIGINT,
	-- Line description used when this component produces an invoice line.
	"name" VARCHAR(160) NOT NULL,
	-- flat | per_unit | package | tiered. tiered defers to plan_tiers for the actual prices.
	"charge_type" VARCHAR(20) NOT NULL DEFAULT 'per_unit',
	-- graduated | volume, for tiered components. Graduated charges each tier its own rate as you pass through it; volume charges every unit at the rate of the tier you land in. The same tiers and the same usage give very different bills.
	"tier_mode" VARCHAR(16),
	-- Price per unit in minor units, for per_unit components. Null when the price comes from tiers.
	"unit_amount_minor" BIGINT,
	-- Fixed charge per period, for flat components.
	"flat_amount_minor" BIGINT,
	-- Units per package, for package pricing — 1000 emails at a time. Partial packages round up.
	"package_size" INTEGER,
	-- Free allowance subtracted before pricing, which is how a plan says "the first 10,000 requests are on us".
	"included_units" DECIMAL(20,6),
	-- none | by_day | by_second. Recurring fees prorate; metered charges never do, because usage is already measured in real time.
	"proration_mode" VARCHAR(20) NOT NULL DEFAULT 'none',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "plan_components" IS 'One charge inside a plan. Making a plan a list of components is the decision that keeps the pricing model open: a new packaging idea is rows, not a migration and a new column nobody else populates.';
COMMENT ON COLUMN "plan_components"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "plan_components"."plan_id" IS 'Plan this charge belongs to.';
COMMENT ON COLUMN "plan_components"."meter_id" IS 'Meter being charged for. Null for a flat platform fee that has no usage behind it.';
COMMENT ON COLUMN "plan_components"."name" IS 'Line description used when this component produces an invoice line.';
COMMENT ON COLUMN "plan_components"."charge_type" IS 'flat | per_unit | package | tiered. tiered defers to plan_tiers for the actual prices.';
COMMENT ON COLUMN "plan_components"."tier_mode" IS 'graduated | volume, for tiered components. Graduated charges each tier its own rate as you pass through it; volume charges every unit at the rate of the tier you land in. The same tiers and the same usage give very different bills.';
COMMENT ON COLUMN "plan_components"."unit_amount_minor" IS 'Price per unit in minor units, for per_unit components. Null when the price comes from tiers.';
COMMENT ON COLUMN "plan_components"."flat_amount_minor" IS 'Fixed charge per period, for flat components.';
COMMENT ON COLUMN "plan_components"."package_size" IS 'Units per package, for package pricing — 1000 emails at a time. Partial packages round up.';
COMMENT ON COLUMN "plan_components"."included_units" IS 'Free allowance subtracted before pricing, which is how a plan says "the first 10,000 requests are on us".';
COMMENT ON COLUMN "plan_components"."proration_mode" IS 'none | by_day | by_second. Recurring fees prorate; metered charges never do, because usage is already measured in real time.';

CREATE INDEX "idx_plan_components_plan"
ON "plan_components" ("plan_id");

CREATE TABLE IF NOT EXISTS "plan_tiers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Component these tiers price.
	"component_id" BIGINT NOT NULL,
	-- Position in the ladder, starting at 0. Tiers must be contiguous and ascending.
	"tier_index" SMALLINT NOT NULL,
	-- Inclusive upper bound of the tier. Null marks the final, unbounded tier — the only clean way to express "and everything above".
	"up_to_units" DECIMAL(20,6),
	-- Price per unit within this tier, in minor units. Zero is legitimate and is how a free allowance tier is written.
	"unit_amount_minor" BIGINT NOT NULL DEFAULT 0,
	-- Fixed fee charged for entering this tier at all, added on top of the per-unit amount.
	"flat_amount_minor" BIGINT NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "plan_tiers" IS 'The price ladder as rows, and the centre of the schema. Encoding tiers as JSON or as columns named tier1_price works until someone asks which customers are priced above 100,000 units, or until a five-tier plan meets a three-column table; as rows the ladder is queryable, diffable, and identical whether it has two tiers or twenty.';
COMMENT ON COLUMN "plan_tiers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "plan_tiers"."component_id" IS 'Component these tiers price.';
COMMENT ON COLUMN "plan_tiers"."tier_index" IS 'Position in the ladder, starting at 0. Tiers must be contiguous and ascending.';
COMMENT ON COLUMN "plan_tiers"."up_to_units" IS 'Inclusive upper bound of the tier. Null marks the final, unbounded tier — the only clean way to express "and everything above".';
COMMENT ON COLUMN "plan_tiers"."unit_amount_minor" IS 'Price per unit within this tier, in minor units. Zero is legitimate and is how a free allowance tier is written.';
COMMENT ON COLUMN "plan_tiers"."flat_amount_minor" IS 'Fixed fee charged for entering this tier at all, added on top of the per-unit amount.';

CREATE UNIQUE INDEX "uq_plan_tiers_ladder"
ON "plan_tiers" ("component_id", "tier_index");

CREATE TABLE IF NOT EXISTS "subscriptions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Customer being billed.
	"customer_id" BIGINT NOT NULL,
	-- Plan version in force. Points at a specific version, so a price change elsewhere cannot reprice this subscription silently.
	"plan_id" BIGINT NOT NULL,
	-- trialing | active | past_due | paused | canceled. past_due is what dunning acts on.
	"status" VARCHAR(20) NOT NULL DEFAULT 'trialing',
	-- Multiplier for flat and per-seat components. Metered components ignore it.
	"quantity" INTEGER NOT NULL DEFAULT 1,
	-- Day of month periods start on. Stored so a February signup keeps billing on the 30th where the month allows.
	"billing_anchor_day" SMALLINT,
	-- Start of the open period. Usage is aggregated between this and the end.
	"current_period_start" TIMESTAMP NOT NULL,
	-- End of the open period; the moment invoicing runs.
	"current_period_end" TIMESTAMP NOT NULL,
	-- First activation, which survives plan changes.
	"started_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- When cancellation was requested. Access usually continues to period end, which is why this is not the same as ended_at.
	"canceled_at" TIMESTAMP,
	-- When service actually stopped and the final invoice was cut.
	"ended_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscriptions" IS 'The billing relationship. The period columns are the clock the whole system runs on: aggregation, invoicing and proration are all defined relative to them, not to the calendar month.';
COMMENT ON COLUMN "subscriptions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscriptions"."customer_id" IS 'Customer being billed.';
COMMENT ON COLUMN "subscriptions"."plan_id" IS 'Plan version in force. Points at a specific version, so a price change elsewhere cannot reprice this subscription silently.';
COMMENT ON COLUMN "subscriptions"."status" IS 'trialing | active | past_due | paused | canceled. past_due is what dunning acts on.';
COMMENT ON COLUMN "subscriptions"."quantity" IS 'Multiplier for flat and per-seat components. Metered components ignore it.';
COMMENT ON COLUMN "subscriptions"."billing_anchor_day" IS 'Day of month periods start on. Stored so a February signup keeps billing on the 30th where the month allows.';
COMMENT ON COLUMN "subscriptions"."current_period_start" IS 'Start of the open period. Usage is aggregated between this and the end.';
COMMENT ON COLUMN "subscriptions"."current_period_end" IS 'End of the open period; the moment invoicing runs.';
COMMENT ON COLUMN "subscriptions"."started_at" IS 'First activation, which survives plan changes.';
COMMENT ON COLUMN "subscriptions"."canceled_at" IS 'When cancellation was requested. Access usually continues to period end, which is why this is not the same as ended_at.';
COMMENT ON COLUMN "subscriptions"."ended_at" IS 'When service actually stopped and the final invoice was cut.';

CREATE INDEX "idx_subscriptions_customer_status"
ON "subscriptions" ("customer_id", "status");
CREATE INDEX "idx_subscriptions_period_end"
ON "subscriptions" ("current_period_end", "status");

CREATE TABLE IF NOT EXISTS "subscription_changes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Subscription being changed.
	"subscription_id" BIGINT NOT NULL,
	-- Plan before the change. Null for the initial activation.
	"from_plan_id" BIGINT,
	-- Plan after the change.
	"to_plan_id" BIGINT NOT NULL,
	-- Seat count before the change.
	"from_quantity" INTEGER,
	-- Seat count after the change.
	"to_quantity" INTEGER NOT NULL,
	-- upgrade | downgrade | quantity | pause | resume | cancel. Upgrades usually bill immediately, downgrades usually wait for period end.
	"change_type" VARCHAR(20) NOT NULL,
	-- When the new terms take effect, which can be in the future for a scheduled downgrade.
	"effective_at" TIMESTAMP NOT NULL,
	-- Unused value of the old plan for the remainder of the period, credited back.
	"proration_credit_minor" BIGINT NOT NULL DEFAULT 0,
	-- Cost of the new plan for that same remainder. The pair of amounts is the whole of proration: unwind the rest of what was paid, charge the rest of what is now owed.
	"proration_charge_minor" BIGINT NOT NULL DEFAULT 0,
	-- When the change was requested.
	"created_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscription_changes" IS 'An append-only history of plan moves, with proration computed at the moment of the change rather than at invoicing. Recomputing it later is impossible once the plan version it referenced has been superseded.';
COMMENT ON COLUMN "subscription_changes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscription_changes"."subscription_id" IS 'Subscription being changed.';
COMMENT ON COLUMN "subscription_changes"."from_plan_id" IS 'Plan before the change. Null for the initial activation.';
COMMENT ON COLUMN "subscription_changes"."to_plan_id" IS 'Plan after the change.';
COMMENT ON COLUMN "subscription_changes"."from_quantity" IS 'Seat count before the change.';
COMMENT ON COLUMN "subscription_changes"."to_quantity" IS 'Seat count after the change.';
COMMENT ON COLUMN "subscription_changes"."change_type" IS 'upgrade | downgrade | quantity | pause | resume | cancel. Upgrades usually bill immediately, downgrades usually wait for period end.';
COMMENT ON COLUMN "subscription_changes"."effective_at" IS 'When the new terms take effect, which can be in the future for a scheduled downgrade.';
COMMENT ON COLUMN "subscription_changes"."proration_credit_minor" IS 'Unused value of the old plan for the remainder of the period, credited back.';
COMMENT ON COLUMN "subscription_changes"."proration_charge_minor" IS 'Cost of the new plan for that same remainder. The pair of amounts is the whole of proration: unwind the rest of what was paid, charge the rest of what is now owed.';
COMMENT ON COLUMN "subscription_changes"."created_at" IS 'When the change was requested.';

CREATE INDEX "idx_subscription_changes_timeline"
ON "subscription_changes" ("subscription_id", "effective_at");

CREATE TABLE IF NOT EXISTS "usage_records" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Subscription that consumed the resource. Recorded at ingest so a later plan change cannot reassign old usage.
	"subscription_id" BIGINT NOT NULL,
	-- What was measured.
	"meter_id" BIGINT NOT NULL,
	-- Units consumed. Decimal because GB-hours and fractional compute time are real; the rounding to billable units happens at aggregation.
	"quantity" DECIMAL(20,6) NOT NULL,
	-- When consumption happened, not when it was reported. Late events must land in the period they belong to.
	"occurred_at" TIMESTAMP NOT NULL,
	-- Client-supplied deduplication key. Metering clients retry, and a double-counted event is a customer-visible overcharge.
	"idempotency_key" VARCHAR(120) UNIQUE,
	-- Dimensions for breakdowns: region, endpoint, model. Not priced, but this is what a usage dashboard groups by.
	"properties" JSONB,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "usage_records" IS 'Raw metering events, append-only and never edited. This is the largest table in the system and the one auditors ask about, so corrections are compensating rows rather than updates.';
COMMENT ON COLUMN "usage_records"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "usage_records"."subscription_id" IS 'Subscription that consumed the resource. Recorded at ingest so a later plan change cannot reassign old usage.';
COMMENT ON COLUMN "usage_records"."meter_id" IS 'What was measured.';
COMMENT ON COLUMN "usage_records"."quantity" IS 'Units consumed. Decimal because GB-hours and fractional compute time are real; the rounding to billable units happens at aggregation.';
COMMENT ON COLUMN "usage_records"."occurred_at" IS 'When consumption happened, not when it was reported. Late events must land in the period they belong to.';
COMMENT ON COLUMN "usage_records"."idempotency_key" IS 'Client-supplied deduplication key. Metering clients retry, and a double-counted event is a customer-visible overcharge.';
COMMENT ON COLUMN "usage_records"."properties" IS 'Dimensions for breakdowns: region, endpoint, model. Not priced, but this is what a usage dashboard groups by.';

CREATE INDEX "idx_usage_records_window"
ON "usage_records" ("subscription_id", "meter_id", "occurred_at");

CREATE TABLE IF NOT EXISTS "usage_aggregates" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Subscription summarised.
	"subscription_id" BIGINT NOT NULL,
	-- Meter summarised.
	"meter_id" BIGINT NOT NULL,
	-- Start of the billing period, copied from the subscription so the grain survives a later period change.
	"period_start" TIMESTAMP NOT NULL,
	-- End of the billing period.
	"period_end" TIMESTAMP NOT NULL,
	-- Aggregated value after applying the meter aggregation function.
	"quantity" DECIMAL(20,6) NOT NULL DEFAULT 0,
	-- Quantity after included units and rounding. Keeping both makes an invoice dispute answerable: here is what you used, here is what we charged for.
	"billable_quantity" DECIMAL(20,6) NOT NULL DEFAULT 0,
	-- Set when the period closes and late events are no longer accepted. An invoice may only be issued from final rows.
	"is_final" BOOLEAN NOT NULL DEFAULT false,
	-- Last recomputation time.
	"computed_at" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "usage_aggregates" IS 'One row per subscription, meter and period, recomputed as events arrive and frozen at close. The unique key makes the aggregation job idempotent: a rerun overwrites its own row instead of adding a second, larger bill.';
COMMENT ON COLUMN "usage_aggregates"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "usage_aggregates"."subscription_id" IS 'Subscription summarised.';
COMMENT ON COLUMN "usage_aggregates"."meter_id" IS 'Meter summarised.';
COMMENT ON COLUMN "usage_aggregates"."period_start" IS 'Start of the billing period, copied from the subscription so the grain survives a later period change.';
COMMENT ON COLUMN "usage_aggregates"."period_end" IS 'End of the billing period.';
COMMENT ON COLUMN "usage_aggregates"."quantity" IS 'Aggregated value after applying the meter aggregation function.';
COMMENT ON COLUMN "usage_aggregates"."billable_quantity" IS 'Quantity after included units and rounding. Keeping both makes an invoice dispute answerable: here is what you used, here is what we charged for.';
COMMENT ON COLUMN "usage_aggregates"."is_final" IS 'Set when the period closes and late events are no longer accepted. An invoice may only be issued from final rows.';
COMMENT ON COLUMN "usage_aggregates"."computed_at" IS 'Last recomputation time.';

CREATE UNIQUE INDEX "uq_usage_aggregates_grain"
ON "usage_aggregates" ("subscription_id", "meter_id", "period_start");

CREATE TABLE IF NOT EXISTS "invoices" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Customer billed.
	"customer_id" BIGINT NOT NULL,
	-- Subscription billed. Null for one-off invoices that belong to no subscription.
	"subscription_id" BIGINT,
	-- Sequential document number required by tax authorities. Gapless numbering is a legal requirement in many jurisdictions, which is why it is not the row id.
	"number" VARCHAR(40) NOT NULL UNIQUE,
	-- draft | open | paid | uncollectible | void. Draft invoices can change; anything past draft is corrected by a credit note, never by an edit.
	"status" VARCHAR(20) NOT NULL DEFAULT 'draft',
	-- Snapshotted from the customer at finalisation.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- Service period covered, printed on the document.
	"period_start" TIMESTAMP,
	-- End of the service period.
	"period_end" TIMESTAMP,
	-- Sum of line amounts before credits and tax, in minor units.
	"subtotal_minor" BIGINT NOT NULL DEFAULT 0,
	-- Prepaid balance consumed by this invoice, recorded as a positive number and subtracted.
	"credit_applied_minor" BIGINT NOT NULL DEFAULT 0,
	-- Tax computed at finalisation, snapshotted because rates change.
	"tax_minor" BIGINT NOT NULL DEFAULT 0,
	-- Amount actually due after credits and tax.
	"total_minor" BIGINT NOT NULL DEFAULT 0,
	-- Cumulative settlement, so partial payments are representable.
	"amount_paid_minor" BIGINT NOT NULL DEFAULT 0,
	-- Payment deadline, the clock dunning works from.
	"due_at" TIMESTAMP,
	-- When the invoice became immutable and got its number.
	"finalized_at" TIMESTAMP,
	-- When it was settled in full.
	"paid_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "invoices" IS 'A financial document, not a view. Every total is stored rather than derived, because the invoice has to say the same thing in five years even after plans, tax rates and the tiers behind it have all been rewritten.';
COMMENT ON COLUMN "invoices"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "invoices"."customer_id" IS 'Customer billed.';
COMMENT ON COLUMN "invoices"."subscription_id" IS 'Subscription billed. Null for one-off invoices that belong to no subscription.';
COMMENT ON COLUMN "invoices"."number" IS 'Sequential document number required by tax authorities. Gapless numbering is a legal requirement in many jurisdictions, which is why it is not the row id.';
COMMENT ON COLUMN "invoices"."status" IS 'draft | open | paid | uncollectible | void. Draft invoices can change; anything past draft is corrected by a credit note, never by an edit.';
COMMENT ON COLUMN "invoices"."currency_code" IS 'Snapshotted from the customer at finalisation.';
COMMENT ON COLUMN "invoices"."period_start" IS 'Service period covered, printed on the document.';
COMMENT ON COLUMN "invoices"."period_end" IS 'End of the service period.';
COMMENT ON COLUMN "invoices"."subtotal_minor" IS 'Sum of line amounts before credits and tax, in minor units.';
COMMENT ON COLUMN "invoices"."credit_applied_minor" IS 'Prepaid balance consumed by this invoice, recorded as a positive number and subtracted.';
COMMENT ON COLUMN "invoices"."tax_minor" IS 'Tax computed at finalisation, snapshotted because rates change.';
COMMENT ON COLUMN "invoices"."total_minor" IS 'Amount actually due after credits and tax.';
COMMENT ON COLUMN "invoices"."amount_paid_minor" IS 'Cumulative settlement, so partial payments are representable.';
COMMENT ON COLUMN "invoices"."due_at" IS 'Payment deadline, the clock dunning works from.';
COMMENT ON COLUMN "invoices"."finalized_at" IS 'When the invoice became immutable and got its number.';
COMMENT ON COLUMN "invoices"."paid_at" IS 'When it was settled in full.';

CREATE INDEX "idx_invoices_customer_status"
ON "invoices" ("customer_id", "status");
CREATE INDEX "idx_invoices_due"
ON "invoices" ("status", "due_at");

CREATE TABLE IF NOT EXISTS "invoice_line_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent invoice.
	"invoice_id" BIGINT NOT NULL,
	-- Component that generated this line. Null for manual adjustments and credits.
	"plan_component_id" BIGINT,
	-- Meter behind a usage line. Null for flat fees.
	"meter_id" BIGINT,
	-- Grant a credit line draws from, which is how prepaid balance consumption becomes visible on the document.
	"credit_grant_id" BIGINT,
	-- subscription | usage | tier | proration | credit | adjustment | tax. Tier lines are how a graduated charge shows its working.
	"line_type" VARCHAR(20) NOT NULL DEFAULT 'usage',
	-- Printed text, e.g. "API requests 10,001-50,000 at $0.002".
	"description" VARCHAR(255) NOT NULL,
	-- Which tier this line represents, for graduated pricing where one meter produces several lines.
	"tier_index" SMALLINT,
	-- Units billed on this line.
	"quantity" DECIMAL(20,6) NOT NULL DEFAULT 0,
	-- Price per unit applied, snapshotted from the tier or component at finalisation.
	"unit_amount_minor" BIGINT NOT NULL DEFAULT 0,
	-- Line total in minor units. Negative for credits and refunds.
	"amount_minor" BIGINT NOT NULL,
	-- Service window for this line, which differs from the invoice period on proration lines.
	"period_start" TIMESTAMP,
	-- End of that window.
	"period_end" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "invoice_line_items" IS 'The arithmetic of the invoice, one row per charge. Graduated pricing emits one line per tier crossed on purpose: a customer who can see 10,000 units at zero, 40,000 at two tenths of a cent and the rest at one tenth does not open a support ticket asking how the number was reached.';
COMMENT ON COLUMN "invoice_line_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "invoice_line_items"."invoice_id" IS 'Parent invoice.';
COMMENT ON COLUMN "invoice_line_items"."plan_component_id" IS 'Component that generated this line. Null for manual adjustments and credits.';
COMMENT ON COLUMN "invoice_line_items"."meter_id" IS 'Meter behind a usage line. Null for flat fees.';
COMMENT ON COLUMN "invoice_line_items"."credit_grant_id" IS 'Grant a credit line draws from, which is how prepaid balance consumption becomes visible on the document.';
COMMENT ON COLUMN "invoice_line_items"."line_type" IS 'subscription | usage | tier | proration | credit | adjustment | tax. Tier lines are how a graduated charge shows its working.';
COMMENT ON COLUMN "invoice_line_items"."description" IS 'Printed text, e.g. "API requests 10,001-50,000 at $0.002".';
COMMENT ON COLUMN "invoice_line_items"."tier_index" IS 'Which tier this line represents, for graduated pricing where one meter produces several lines.';
COMMENT ON COLUMN "invoice_line_items"."quantity" IS 'Units billed on this line.';
COMMENT ON COLUMN "invoice_line_items"."unit_amount_minor" IS 'Price per unit applied, snapshotted from the tier or component at finalisation.';
COMMENT ON COLUMN "invoice_line_items"."amount_minor" IS 'Line total in minor units. Negative for credits and refunds.';
COMMENT ON COLUMN "invoice_line_items"."period_start" IS 'Service window for this line, which differs from the invoice period on proration lines.';
COMMENT ON COLUMN "invoice_line_items"."period_end" IS 'End of that window.';

CREATE INDEX "idx_invoice_lines_invoice"
ON "invoice_line_items" ("invoice_id", "line_type");

CREATE TABLE IF NOT EXISTS "credit_grants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Customer holding the credit.
	"customer_id" BIGINT NOT NULL,
	-- Original value granted, in minor units.
	"amount_minor" BIGINT NOT NULL,
	-- Unconsumed balance. Decremented as invoices draw on it; the invoice lines record where it went.
	"remaining_minor" BIGINT NOT NULL,
	-- Credit is currency-specific and never converted.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- prepaid | promotional | goodwill | refund | migration. Prepaid credit was paid for; promotional credit was not, and finance reports the two very differently.
	"reason" VARCHAR(24) NOT NULL DEFAULT 'prepaid',
	-- Consumption order, lowest first. Expiring promotional credit should be spent before purchased balance that never expires.
	"priority" SMALLINT NOT NULL DEFAULT 100,
	-- When the credit becomes usable.
	"effective_at" TIMESTAMP NOT NULL DEFAULT now(),
	-- Expiry. Null means it never expires, which is usually correct for money the customer actually paid.
	"expires_at" TIMESTAMP,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "credit_grants" IS 'Prepaid and granted balances as discrete grants rather than one number on the customer. Separate grants are what make expiry, consumption order and "which promotion did this come from" answerable at all.';
COMMENT ON COLUMN "credit_grants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "credit_grants"."customer_id" IS 'Customer holding the credit.';
COMMENT ON COLUMN "credit_grants"."amount_minor" IS 'Original value granted, in minor units.';
COMMENT ON COLUMN "credit_grants"."remaining_minor" IS 'Unconsumed balance. Decremented as invoices draw on it; the invoice lines record where it went.';
COMMENT ON COLUMN "credit_grants"."currency_code" IS 'Credit is currency-specific and never converted.';
COMMENT ON COLUMN "credit_grants"."reason" IS 'prepaid | promotional | goodwill | refund | migration. Prepaid credit was paid for; promotional credit was not, and finance reports the two very differently.';
COMMENT ON COLUMN "credit_grants"."priority" IS 'Consumption order, lowest first. Expiring promotional credit should be spent before purchased balance that never expires.';
COMMENT ON COLUMN "credit_grants"."effective_at" IS 'When the credit becomes usable.';
COMMENT ON COLUMN "credit_grants"."expires_at" IS 'Expiry. Null means it never expires, which is usually correct for money the customer actually paid.';

CREATE INDEX "idx_credit_grants_consumption"
ON "credit_grants" ("customer_id", "priority", "expires_at");

CREATE TABLE IF NOT EXISTS "dunning_attempts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Overdue invoice being chased.
	"invoice_id" BIGINT NOT NULL,
	-- Position in the retry schedule, typically day 1, 3, 5, 7 after failure.
	"attempt_number" SMALLINT NOT NULL,
	-- When the attempt should run. The worker queries this, so retries survive a restart.
	"scheduled_at" TIMESTAMP NOT NULL,
	-- When it actually ran. Null while pending.
	"attempted_at" TIMESTAMP,
	-- succeeded | failed | skipped. Null while pending.
	"outcome" VARCHAR(20),
	-- Gateway decline code. insufficient_funds is worth retrying; card_stolen never is, and telling them apart is most of what dunning does.
	"failure_code" VARCHAR(60),
	-- retry | email | downgrade | cancel. The escalation ladder, recorded per attempt so the customer-visible story stays consistent.
	"next_action" VARCHAR(24),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "dunning_attempts" IS 'The recovery process as rows. Scheduling attempts in the database rather than in a queue means a failed payment survives a deploy, an incident and a queue flush — and gives support a straight answer to why an account was suspended.';
COMMENT ON COLUMN "dunning_attempts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "dunning_attempts"."invoice_id" IS 'Overdue invoice being chased.';
COMMENT ON COLUMN "dunning_attempts"."attempt_number" IS 'Position in the retry schedule, typically day 1, 3, 5, 7 after failure.';
COMMENT ON COLUMN "dunning_attempts"."scheduled_at" IS 'When the attempt should run. The worker queries this, so retries survive a restart.';
COMMENT ON COLUMN "dunning_attempts"."attempted_at" IS 'When it actually ran. Null while pending.';
COMMENT ON COLUMN "dunning_attempts"."outcome" IS 'succeeded | failed | skipped. Null while pending.';
COMMENT ON COLUMN "dunning_attempts"."failure_code" IS 'Gateway decline code. insufficient_funds is worth retrying; card_stolen never is, and telling them apart is most of what dunning does.';
COMMENT ON COLUMN "dunning_attempts"."next_action" IS 'retry | email | downgrade | cancel. The escalation ladder, recorded per attempt so the customer-visible story stays consistent.';

CREATE UNIQUE INDEX "uq_dunning_attempt_number"
ON "dunning_attempts" ("invoice_id", "attempt_number");
CREATE INDEX "idx_dunning_due"
ON "dunning_attempts" ("scheduled_at", "outcome");

